css:
.d-gh{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-gh-card{display:flex;flex-direction:column;gap:2px;padding:18px 20px;border:1px dashed var(--line);border-radius:10px;text-align:center}
.d-gh-card b{font-size:13px}
.d-gh-card span{font-size:11px;color:var(--muted)}
.d-gh-hand{position:absolute;left:50%;bottom:44px;display:flex;align-items:center;gap:2px;opacity:0;transition:opacity 200ms var(--ease)}
.d-gh-hand i{display:block;width:14px;height:14px;border-radius:50%;background:var(--ink);box-shadow:0 0 0 6px color-mix(in srgb,var(--ink) 12%,transparent)}
.d-gh-hand:after{content:"";display:block;width:46px;height:1px;background:var(--ink);opacity:.35}
.d-gh-hand.on{opacity:1;animation:d-gesture-hint-sweep 1.8s var(--ease) 2 both}
@keyframes d-gesture-hint-sweep{0%{transform:translateX(-46px)}55%{transform:translateX(46px)}100%{transform:translateX(-46px)}}
.d-gh-note{position:absolute;bottom:8px;margin:0}
.d-gh-note button{border:0;background:none;color:var(--faint);font:inherit;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;cursor:pointer;text-decoration:underline}

init:
root => {
  var hand = root.querySelector('[data-hand]');
  var again = root.querySelector('[data-again]');
  if (!hand) return;
  var play = function () { hand.classList.remove('on'); void hand.offsetWidth; hand.classList.add('on'); };
  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) play();
  if (again) again.addEventListener('click', play);
  hand.addEventListener('animationend', function () { hand.classList.remove('on'); });
}
